using System.ComponentModel;
using System.Diagnostics;
using MediaMan.Core.Domain;
using MediaMan.Playback.Probing;

namespace MediaMan.Playback.Tests.Probing;

/// <summary>Runs real ffprobe on tiny samples generated by ffmpeg; skipped when either tool isn't on PATH (SPEC §10.4).</summary>
public sealed class FfprobeMediaProbeIntegrationTests : IDisposable
{
    private static readonly Lazy<bool> _toolsAvailable = new(() => CanRun("ffmpeg") && CanRun("ffprobe"));

    private readonly string _dir = Path.Combine(Path.GetTempPath(), "mediaman-tests", Guid.NewGuid().ToString("N"));
    private readonly FfprobeMediaProbe _probe = new(new FfprobeOptions());

    public FfprobeMediaProbeIntegrationTests() => Directory.CreateDirectory(_dir);

    public void Dispose() => Directory.Delete(_dir, recursive: true);

    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    [Fact]
    public async Task Probes_a_matroska_file_with_video_audio_and_subtitles()
    {
        RequireTools();
        var srt = Path.Combine(_dir, "sub.srt");
        await File.WriteAllTextAsync(srt, "1\n00:00:00,000 --> 00:00:01,000\nHello\n", Ct);
        var file = Path.Combine(_dir, "Sample Movie (2020).mkv");
        await FfmpegAsync(
            "-f", "lavfi", "-i", "testsrc=size=320x240:rate=10:duration=1", "-f", "lavfi", "-i", "sine=duration=1", "-i", srt,
            "-map", "0", "-map", "1", "-map", "2", "-c:v", "libx264", "-c:a", "aac", "-c:s", "srt",
            "-metadata:s:a:0", "language=eng", "-metadata:s:s:0", "language=fre", "-disposition:s:0", "forced", file);

        var result = await _probe.ProbeAsync(file, Ct);

        result.Container.Should().Be("matroska,webm");
        result.Duration.Should().BeCloseTo(TimeSpan.FromSeconds(1), TimeSpan.FromMilliseconds(200));
        result.HdrFormat.Should().BeNull();
        result.Streams.Select(s => (s.Type, s.Codec)).Should().Equal(
            (MediaStreamType.Video, "h264"), (MediaStreamType.Audio, "aac"), (MediaStreamType.Subtitle, "subrip"));
        result.Streams[0].Width.Should().Be(320);
        result.Streams[0].Height.Should().Be(240);
        result.Streams[1].Language.Should().Be("eng");
        result.Streams[2].Language.Should().Be("fre");
        result.Streams[2].IsForced.Should().BeTrue();
    }

    [Fact]
    public async Task Detects_hdr10_from_the_transfer_function()
    {
        RequireTools();
        var file = Path.Combine(_dir, "hdr.mp4");
        await FfmpegAsync(
            "-f", "lavfi", "-i", "testsrc=size=320x240:rate=10:duration=1", "-c:v", "libx264",
            "-color_primaries", "bt2020", "-color_trc", "smpte2084", "-colorspace", "bt2020nc", file);

        var result = await _probe.ProbeAsync(file, Ct);

        result.Container.Should().StartWith("mov,mp4");
        result.HdrFormat.Should().Be("HDR10");
    }

    [Fact]
    public async Task A_file_that_is_not_media_is_invalid_data()
    {
        RequireTools();
        var file = Path.Combine(_dir, "broken.mkv");
        await File.WriteAllTextAsync(file, "this is not a video", Ct);

        var probe = () => _probe.ProbeAsync(file, Ct);

        await probe.Should().ThrowAsync<InvalidDataException>().WithMessage("*broken.mkv*");
    }

    [Fact]
    public async Task A_missing_file_is_not_found()
    {
        var probe = () => _probe.ProbeAsync(Path.Combine(_dir, "missing.mkv"), Ct);

        await probe.Should().ThrowAsync<FileNotFoundException>();
    }

    [Fact]
    public async Task A_missing_ffprobe_fails_with_the_fix()
    {
        var file = Path.Combine(_dir, "movie.mkv");
        await File.WriteAllTextAsync(file, "", Ct);
        var probe = new FfprobeMediaProbe(new FfprobeOptions { ExecutablePath = Path.Combine(_dir, "no-such-ffprobe") });

        var run = () => probe.ProbeAsync(file, Ct);

        await run.Should().ThrowAsync<InvalidOperationException>().WithMessage("*Install ffmpeg*MediaMan:Tools:FfprobePath*");
    }

    private static void RequireTools() =>
        Assert.SkipUnless(_toolsAvailable.Value, "ffmpeg and ffprobe must be on PATH for the ffprobe integration tests.");

    private static async Task FfmpegAsync(params string[] args)
    {
        var startInfo = new ProcessStartInfo("ffmpeg") { RedirectStandardError = true, UseShellExecute = false, CreateNoWindow = true };
        foreach (var arg in (string[])["-v", "error", "-y", .. args])
        {
            startInfo.ArgumentList.Add(arg);
        }

        using var process = Process.Start(startInfo)!;
        var stderr = await process.StandardError.ReadToEndAsync(Ct);
        await process.WaitForExitAsync(Ct);
        process.ExitCode.Should().Be(0, $"ffmpeg should generate the sample: {stderr}");
    }

    private static bool CanRun(string tool)
    {
        try
        {
            using var process = Process.Start(new ProcessStartInfo(tool, "-version")
            {
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            })!;
            process.StandardOutput.ReadToEnd();
            process.WaitForExit();
            return process.ExitCode == 0;
        }
        catch (Win32Exception)
        {
            return false;
        }
    }
}
